import{_ as a,o as n,c as t,a2 as s}from"./chunks/framework.e4u2V5E7.js";const h=JSON.parse('{"title":"Feature Development Playbook","description":"Engineering playbook for feature development workflow","frontmatter":{"title":"Feature Development Playbook","description":"Engineering playbook for feature development workflow"},"headers":[],"relativePath":"playbooks/feature-development.md","filePath":"playbooks/feature-development.md","lastUpdated":1784485118000}'),i={name:"playbooks/feature-development.md"};function o(l,e,r,d,p,c){return n(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="feature-development-playbook" tabindex="-1">Feature Development Playbook <a class="header-anchor" href="#feature-development-playbook" aria-label="Permalink to &quot;Feature Development Playbook&quot;">​</a></h1><h1 id="playbook-feature-development" tabindex="-1">Playbook: Feature Development <a class="header-anchor" href="#playbook-feature-development" aria-label="Permalink to &quot;Playbook: Feature Development&quot;">​</a></h1><p><strong>Purpose:</strong> Standard procedure for developing a new feature from requirements to deployment.</p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><h3 id="phase-1-requirements-5-min" tabindex="-1">Phase 1: Requirements (5 min) <a class="header-anchor" href="#phase-1-requirements-5-min" aria-label="Permalink to &quot;Phase 1: Requirements (5 min)&quot;">​</a></h3><ol><li>Clarify the feature requirement</li><li>Identify affected components</li><li>Check if existing skills/patterns apply</li><li>Estimate complexity (simple / moderate / complex)</li></ol><h3 id="phase-2-planning-10-min" tabindex="-1">Phase 2: Planning (10 min) <a class="header-anchor" href="#phase-2-planning-10-min" aria-label="Permalink to &quot;Phase 2: Planning (10 min)&quot;">​</a></h3><ol><li>Load relevant skill: <code>@skill [relevant-skill]</code></li><li>Check existing patterns in the codebase</li><li>Plan file changes (which files to create/modify)</li><li>Identify dependencies on other features</li></ol><h3 id="phase-3-implementation-varies" tabindex="-1">Phase 3: Implementation (varies) <a class="header-anchor" href="#phase-3-implementation-varies" aria-label="Permalink to &quot;Phase 3: Implementation (varies)&quot;">​</a></h3><ol><li><strong>Create files</strong> following naming conventions</li><li><strong>Follow patterns</strong> from loaded skills</li><li><strong>Write code</strong> adhering to Professional Layer standards</li><li><strong>Add types</strong> — no <code>any</code>, explicit interfaces</li><li><strong>Handle errors</strong> — every async operation, every boundary</li><li><strong>Add i18n</strong> — translation keys for user-facing text</li></ol><h3 id="phase-4-quality-check-10-min" tabindex="-1">Phase 4: Quality Check (10 min) <a class="header-anchor" href="#phase-4-quality-check-10-min" aria-label="Permalink to &quot;Phase 4: Quality Check (10 min)&quot;">​</a></h3><ol><li>Run <code>npm run build</code> — must pass</li><li>Run <code>npm run lint</code> — no errors (if configured)</li><li>Test the feature manually</li><li>Run <code>/review</code> on changed files</li><li>Check accessibility (keyboard, screen reader)</li></ol><h3 id="phase-5-documentation-5-min" tabindex="-1">Phase 5: Documentation (5 min) <a class="header-anchor" href="#phase-5-documentation-5-min" aria-label="Permalink to &quot;Phase 5: Documentation (5 min)&quot;">​</a></h3><ol><li>Update project AGENTS.md if new patterns established</li><li>Add JSDoc to complex functions</li><li>Update README if user-facing changes</li></ol><h3 id="phase-6-deployment" tabindex="-1">Phase 6: Deployment <a class="header-anchor" href="#phase-6-deployment" aria-label="Permalink to &quot;Phase 6: Deployment&quot;">​</a></h3><ol><li>Create feature branch: <code>git checkout -b feat/feature-name</code></li><li>Commit with conventional format: <code>feat(scope): description</code></li><li>Push and create PR</li><li>Vercel auto-deploys preview</li><li>Test preview deployment</li><li>Merge to main (auto-deploys to production)</li></ol><h2 id="file-structure-convention" tabindex="-1">File Structure Convention <a class="header-anchor" href="#file-structure-convention" aria-label="Permalink to &quot;File Structure Convention&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span>├── app/</span></span>
<span class="line"><span>│   └── [feature]/</span></span>
<span class="line"><span>│       ├── page.tsx          # Route page</span></span>
<span class="line"><span>│       ├── layout.tsx        # Optional nested layout</span></span>
<span class="line"><span>│       ├── loading.tsx       # Loading state</span></span>
<span class="line"><span>│       ├── error.tsx         # Error boundary</span></span>
<span class="line"><span>│       └── components/       # Feature-specific components</span></span>
<span class="line"><span>│           ├── FeatureMain.tsx</span></span>
<span class="line"><span>│           └── FeatureItem.tsx</span></span>
<span class="line"><span>├── components/</span></span>
<span class="line"><span>│   └── ui/                   # Shared UI primitives</span></span>
<span class="line"><span>└── lib/</span></span>
<span class="line"><span>    └── [feature].ts          # Feature utilities (if needed)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><h2 id="naming-conventions" tabindex="-1">Naming Conventions <a class="header-anchor" href="#naming-conventions" aria-label="Permalink to &quot;Naming Conventions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Convention</th><th>Example</th></tr></thead><tbody><tr><td>Component file</td><td>PascalCase.tsx</td><td><code>BookingForm.tsx</code></td></tr><tr><td>Utility file</td><td>camelCase.ts</td><td><code>formatDate.ts</code></td></tr><tr><td>API route</td><td>kebab-case</td><td><code>api/booking/route.ts</code></td></tr><tr><td>Page</td><td>kebab-case</td><td><code>app/booking/page.tsx</code></td></tr><tr><td>CSS class</td><td>Tailwind utilities</td><td><code>className=&quot;...&quot;</code></td></tr><tr><td>Translation key</td><td>dot notation</td><td><code>booking.title</code></td></tr><tr><td>Variable</td><td>camelCase</td><td><code>bookingDate</code></td></tr><tr><td>Type/Interface</td><td>PascalCase</td><td><code>BookingFormData</code></td></tr></tbody></table><h2 id="code-review-checklist" tabindex="-1">Code Review Checklist <a class="header-anchor" href="#code-review-checklist" aria-label="Permalink to &quot;Code Review Checklist&quot;">​</a></h2><p>Before pushing, verify:</p><ul><li>[ ] No <code>any</code> types</li><li>[ ] All async operations have error handling</li><li>[ ] i18n keys for all user-facing text</li><li>[ ] Responsive on mobile</li><li>[ ] Keyboard accessible</li><li>[ ] Loading and error states handled</li><li>[ ] No hardcoded values (use constants or env vars)</li><li>[ ] Build passes</li></ul><h2 id="related-commands" tabindex="-1">Related Commands <a class="header-anchor" href="#related-commands" aria-label="Permalink to &quot;Related Commands&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/commands/">Commands Registry</a> for commands used in this playbook.</p><h2 id="related-agents" tabindex="-1">Related Agents <a class="header-anchor" href="#related-agents" aria-label="Permalink to &quot;Related Agents&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/agents/">Agents Registry</a> for agents involved in this playbook.</p>`,27)])])}const u=a(i,[["render",o]]);export{h as __pageData,u as default};
